-- Fairway MVP. Ejecutar una vez en un proyecto nuevo de Supabase.
begin;
create extension if not exists pgcrypto;
create table public.clubs(id uuid primary key default gen_random_uuid(),name text not null,city text not null default 'León',verified boolean not null default false,description text,access_info text,photo text);
create table public.profiles(id uuid primary key references auth.users on delete cascade,name text not null check(length(name) between 2 and 80),age integer not null check(age between 18 and 100),city text not null default 'León',club_id uuid references public.clubs on delete set null,handicap numeric check(handicap between -10 and 54),bio text not null default '' check(length(bio)<=500),photo text not null default '',gallery text[] not null default '{}',availability text[] not null default '{}',holes integer not null default 18 check(holes in(9,18)),style text not null default 'social' check(style in('social','intermedio','competitivo')),hand text default 'derecha',years integer default 0,frequency text default 'Semanal',transport text default 'Indistinto',accepts_guests boolean not null default false,beginner_friendly boolean not null default false,formats text[] default '{}',additional_clubs uuid[] default '{}',gender text default '',occupation text default '',visibility text not null default 'members' check(visibility in('public','members','private')),verified boolean not null default false,created_at timestamptz not null default now(),constraint gallery_limit check(cardinality(gallery)<=6));
create table public.account_roles(user_id uuid primary key references auth.users on delete cascade,is_admin boolean not null default false,suspended boolean not null default false);
create table public.decisions(actor_id uuid references public.profiles on delete cascade,target_id uuid references public.profiles on delete cascade,decision text not null check(decision in('like','pass')),created_at timestamptz default now(),primary key(actor_id,target_id),check(actor_id<>target_id));
create table public.favorites(user_id uuid references public.profiles on delete cascade,target_id uuid references public.profiles on delete cascade,primary key(user_id,target_id),check(user_id<>target_id));
create table public.blocks(user_id uuid references public.profiles on delete cascade,target_id uuid references public.profiles on delete cascade,primary key(user_id,target_id),check(user_id<>target_id));
create table public.matches(id uuid primary key default gen_random_uuid(),user_a uuid not null references public.profiles on delete cascade,user_b uuid not null references public.profiles on delete cascade,created_at timestamptz default now(),unique(user_a,user_b),check(user_a<user_b));
create table public.games(id uuid primary key default gen_random_uuid(),host_id uuid not null references public.profiles on delete cascade,club_id uuid not null references public.clubs,starts_at timestamptz not null,holes integer not null check(holes in(9,18)),capacity integer not null check(capacity between 2 and 4),format text not null,kind text not null check(kind in('social','competitivo')),privacy text not null default 'public' check(privacy in('public','matches','invite')),description text not null check(length(description)<=1000),access_conditions text not null,status text not null default 'open' check(status in('open','full','cancelled','finished')),created_at timestamptz default now());
create table public.game_participants(game_id uuid references public.games on delete cascade,user_id uuid references public.profiles on delete cascade,status text not null default 'requested' check(status in('requested','confirmed','rejected')),access_acknowledged boolean not null default false,primary key(game_id,user_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),match_id uuid unique references public.matches on delete cascade,game_id uuid unique references public.games on delete cascade,check(num_nonnulls(match_id,game_id)=1));
create table public.conversation_members(conversation_id uuid references public.conversations on delete cascade,user_id uuid references public.profiles on delete cascade,last_read_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations on delete cascade,sender_id uuid not null references public.profiles on delete cascade,body text not null check(length(trim(body)) between 1 and 2000),created_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),club_id uuid references public.clubs,name text not null,verified boolean not null default false);
create table public.tees(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses on delete cascade,name text not null,verified boolean not null default false);
create table public.holes(tee_id uuid references public.tees on delete cascade,hole integer check(hole between 1 and 18),par integer check(par between 3 and 6),distance integer,index integer check(index between 1 and 18),primary key(tee_id,hole));
create table public.rounds(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,club_id uuid references public.clubs,played_at date not null,holes integer not null check(holes in(9,18)),tee text not null,course text not null default '',status text not null default 'draft' check(status in('draft','finished','published')),privacy text not null default 'private' check(privacy in('public','followers','private')),verified boolean not null default false,notes text not null default '' check(length(notes)<=2000),scores jsonb not null default '[]',created_at timestamptz not null default now());
create table public.hole_scores(round_id uuid references public.rounds on delete cascade,hole integer check(hole between 1 and 18),par integer check(par between 3 and 6),strokes integer check(strokes between 1 and 30),putts integer check(putts between 0 and 30),fairway boolean,gir boolean,distance integer,index integer,primary key(round_id,hole));
create table public.followers(user_id uuid references public.profiles on delete cascade,target_id uuid references public.profiles on delete cascade,approved boolean not null default false,primary key(user_id,target_id),check(user_id<>target_id));
create table public.posts(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles on delete cascade,body text not null check(length(body) between 1 and 2000),photo text,round_id uuid references public.rounds on delete cascade,privacy text not null default 'public' check(privacy in('public','followers','private')),created_at timestamptz default now());
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,body text not null check(length(body) between 1 and 1000),created_at timestamptz default now());
create table public.reactions(post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,primary key(post_id,user_id));
create table public.reviews(id uuid primary key default gen_random_uuid(),game_id uuid references public.games on delete cascade,reviewer_id uuid references public.profiles on delete cascade,target_id uuid references public.profiles on delete cascade,punctuality integer not null check(punctuality between 1 and 5),respect integer not null check(respect between 1 and 5),pace integer not null check(pace between 1 and 5),company integer not null check(company between 1 and 5),body text check(length(body)<=1000),created_at timestamptz default now(),unique(game_id,reviewer_id,target_id),check(reviewer_id<>target_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles on delete cascade,category text not null,title text not null,read boolean default false,created_at timestamptz default now());
create table public.notification_preferences(user_id uuid references public.profiles on delete cascade,category text not null,enabled boolean not null default true,primary key(user_id,category));
create table public.reports(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles on delete set null,target_id uuid references public.profiles on delete set null,reason text not null check(length(reason) between 5 and 2000),status text default 'pending',created_at timestamptz default now());
create table public.availability(user_id uuid primary key references public.profiles on delete cascade,club_id uuid references public.clubs,starts_at timestamptz not null,expires_at timestamptz not null,holes integer check(holes in(9,18)),check(expires_at>starts_at));
create table public.verification_requests(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles on delete cascade,kind text not null,body text not null,status text default 'pending');
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from account_roles where user_id=auth.uid() and is_admin and not suspended) $$;
create function public.active_user() returns boolean language sql stable security definer set search_path=public as $$ select auth.uid() is not null and not exists(select 1 from account_roles where user_id=auth.uid() and suspended) $$;
create function public.not_blocked(other uuid) returns boolean language sql stable security definer set search_path=public as $$ select not exists(select 1 from blocks where (user_id=auth.uid() and target_id=other) or (target_id=auth.uid() and user_id=other)) $$;
create function public.are_matched(other uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from matches where user_a=least(auth.uid(),other) and user_b=greatest(auth.uid(),other)) $$;
create function public.in_game(g uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from game_participants where game_id=g and user_id=auth.uid() and status='confirmed') $$;
create function public.can_see_game(g uuid) returns boolean language sql stable security definer set search_path=public as $$ select active_user() and exists(select 1 from games where id=g and not_blocked(host_id) and (privacy='public' or host_id=auth.uid() or in_game(g) or (privacy='matches' and are_matched(host_id)))) $$;
create function public.can_chat(c uuid) returns boolean language sql stable security definer set search_path=public as $$ select active_user() and exists(select 1 from conversation_members where conversation_id=c and user_id=auth.uid()) and not exists(select 1 from conversation_members m where conversation_id=c and not not_blocked(m.user_id)) $$;
create function public.can_read_social(owner_id uuid,privacy text) returns boolean language sql stable security definer set search_path=public as $$ select active_user() and not_blocked(owner_id) and (owner_id=auth.uid() or privacy='public' or (privacy='followers' and exists(select 1 from followers where user_id=auth.uid() and target_id=owner_id and approved))) $$;
create function public.on_signup() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,name,age) values(new.id,coalesce(nullif(trim(new.raw_user_meta_data->>'name'),''),'Golfista'),(new.raw_user_meta_data->>'age')::integer);insert into account_roles(user_id) values(new.id);return new;end $$;
create trigger signup after insert on auth.users for each row execute function public.on_signup();
create function public.protect_profile() returns trigger language plpgsql set search_path=public as $$ begin if new.verified is distinct from old.verified and not is_admin() then raise exception 'Solo administración puede verificar perfiles';end if;return new;end $$;
create trigger protect_profile before update on public.profiles for each row execute function public.protect_profile();
create function public.decide(target uuid,choice text) returns uuid language plpgsql security definer set search_path=public as $$ declare mid uuid;cid uuid; begin if not active_user() or target=auth.uid() or not not_blocked(target) or choice not in('like','pass') or not exists(select 1 from profiles where id=target and visibility<>'private') then raise exception 'Decisión no permitida';end if;perform pg_advisory_xact_lock(hashtext(least(auth.uid(),target)::text||greatest(auth.uid(),target)::text));insert into decisions values(auth.uid(),target,choice,now()) on conflict(actor_id,target_id) do update set decision=excluded.decision;if choice='like' and exists(select 1 from decisions where actor_id=target and target_id=auth.uid() and decision='like') then insert into matches(user_a,user_b) values(least(auth.uid(),target),greatest(auth.uid(),target)) on conflict(user_a,user_b) do nothing returning id into mid;if mid is null then select id into mid from matches where user_a=least(auth.uid(),target) and user_b=greatest(auth.uid(),target);return mid;end if;insert into conversations(match_id) values(mid) on conflict(match_id) do update set match_id=excluded.match_id returning id into cid;insert into conversation_members values(cid,auth.uid(),now()),(cid,target,now()) on conflict do nothing;insert into notifications(user_id,category,title) values(auth.uid(),'matches','¡Tienes un nuevo match!'),(target,'matches','¡Tienes un nuevo match!');end if;return mid;end $$;
create function public.request_join(g uuid) returns void language plpgsql security definer set search_path=public as $$ begin perform 1 from games where id=g and status='open' and starts_at>now() and can_see_game(g) for update;if not found then raise exception 'Partida no disponible';end if;insert into game_participants values(g,auth.uid(),'requested',true) on conflict(game_id,user_id) do nothing;if not found then return;end if;insert into notifications(user_id,category,title) select host_id,'games','Nueva solicitud para tu partida' from games where id=g;end $$;
create function public.init_game() returns trigger language plpgsql security definer set search_path=public as $$ declare cid uuid;begin insert into game_participants values(new.id,new.host_id,'confirmed',true);insert into conversations(game_id) values(new.id) returning id into cid;insert into conversation_members values(cid,new.host_id,now());return new;end $$;
create trigger init_game after insert on games for each row execute function public.init_game();
create function public.manage_game(g uuid,player uuid,action text) returns void language plpgsql security definer set search_path=public as $$ declare rec games;cid uuid;begin select * into rec from games where id=g for update;if rec.host_id<>auth.uid() or not active_user() then raise exception 'Solo el organizador';end if;if action in('cancelled','finished') then if rec.status not in('open','full') then raise exception 'La partida ya fue cerrada';end if;if action='finished' and rec.starts_at>now() then raise exception 'La partida todavía no ocurre';end if;update games set status=action where id=g;elsif action in('confirmed','rejected') and rec.status in('open','full') then if player=rec.host_id then raise exception 'El organizador permanece confirmado';end if;if action='confirmed' and (select count(*) from game_participants where game_id=g and status='confirmed')>=rec.capacity then raise exception 'La partida está completa';end if;update game_participants set status=action where game_id=g and user_id=player and status='requested';if not found then raise exception 'Solicitud no disponible';end if;if action='confirmed' then select id into cid from conversations where game_id=g;insert into conversation_members values(cid,player,now()) on conflict do nothing;end if;update games set status=case when (select count(*) from game_participants where game_id=g and status='confirmed')>=rec.capacity then 'full' else 'open' end where id=g;else raise exception 'Acción inválida';end if;end $$;
create function public.validate_round() returns trigger language plpgsql set search_path=public as $$ declare h jsonb;n integer:=0;begin if new.verified and not is_admin() then raise exception 'La captura manual no es verificada';end if;if jsonb_typeof(new.scores)<>'array' or jsonb_array_length(new.scores)<>new.holes then raise exception 'Tarjeta incompleta';end if;for h in select * from jsonb_array_elements(new.scores) loop n:=n+1;if (h->>'hole')::integer<>n or ((h->>'par') is not null and (h->>'par')::integer not between 3 and 6) or ((h->>'strokes') is not null and (h->>'strokes')::integer not between 1 and 30) or ((h->>'putts') is not null and (h->>'putts')::integer not between 0 and 30) then raise exception 'Datos de hoyo inválidos';end if;if new.status<>'draft' and h->>'strokes' is null then raise exception 'Captura todos los hoyos';end if;end loop;return new;end $$;
create trigger validate_round before insert or update on rounds for each row execute function public.validate_round();
create function public.sync_scores() returns trigger language plpgsql security definer set search_path=public as $$ begin delete from hole_scores where round_id=new.id;insert into hole_scores(round_id,hole,par,strokes,putts,fairway,gir,distance,index) select new.id,x.hole,x.par,x.strokes,x.putts,x.fairway,x.gir,x.distance,x.index from jsonb_to_recordset(new.scores) as x(hole integer,par integer,strokes integer,putts integer,fairway boolean,gir boolean,distance integer,index integer);return new;end $$;
create trigger sync_scores after insert or update on rounds for each row execute function public.sync_scores();
create function public.valid_review(g uuid,other uuid) returns boolean language sql stable security definer set search_path=public as $$ select active_user() and exists(select 1 from games where id=g and status='finished') and in_game(g) and exists(select 1 from game_participants where game_id=g and user_id=other and status='confirmed') and not_blocked(other) $$;
create function public.rating_summary() returns table(user_id uuid,rating numeric,review_count bigint) language sql stable security definer set search_path=public as $$ select target_id,round(avg((punctuality+respect+pace+company)/4.0),1),count(*) from reviews where active_user() and not_blocked(target_id) group by target_id $$;
create function public.send_message(c uuid,content text) returns void language plpgsql security definer set search_path=public as $$ begin if not can_chat(c) then raise exception 'Conversación no autorizada';end if;if (select count(*) from messages where sender_id=auth.uid() and created_at>now()-interval '1 minute')>=20 then raise exception 'Espera un momento antes de enviar más mensajes';end if;insert into messages(conversation_id,sender_id,body) values(c,auth.uid(),trim(content));insert into notifications(user_id,category,title) select user_id,'messages','Tienes un nuevo mensaje' from conversation_members where conversation_id=c and user_id<>auth.uid();end $$;
create function public.delete_my_account() returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Inicia sesión';end if;delete from auth.users where id=auth.uid();end $$;
-- RLS activado en todas las tablas, incluso las reservadas para fases posteriores.
do $$ declare t text;begin foreach t in array array['clubs','profiles','account_roles','decisions','favorites','blocks','matches','games','game_participants','conversations','conversation_members','messages','courses','tees','holes','rounds','hole_scores','followers','posts','comments','reactions','reviews','notifications','notification_preferences','reports','availability','verification_requests'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy admin_all on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',t);end loop;end $$;
create policy read_clubs on clubs for select to authenticated using(active_user());
create policy read_profiles on profiles for select to authenticated using(active_user() and (id=auth.uid() or (visibility<>'private' and not_blocked(id))));
create policy edit_profile on profiles for update to authenticated using(active_user() and id=auth.uid()) with check(id=auth.uid());
create policy own_role on account_roles for select to authenticated using(user_id=auth.uid());
create policy own_decisions on decisions for select to authenticated using(active_user() and actor_id=auth.uid());
create policy own_favorites on favorites for all to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid() and not_blocked(target_id));
create policy own_blocks on blocks for all to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_matches on matches for select to authenticated using(active_user() and auth.uid() in(user_a,user_b) and not_blocked(case when user_a=auth.uid() then user_b else user_a end));
create policy read_games on games for select to authenticated using(can_see_game(id));
create policy create_game on games for insert to authenticated with check(active_user() and host_id=auth.uid() and status='open' and starts_at>now());
create policy read_participants on game_participants for select to authenticated using(can_see_game(game_id));
create policy read_conversations on conversations for select to authenticated using(can_chat(id));
create policy read_members on conversation_members for select to authenticated using(can_chat(conversation_id));
create policy mark_read on conversation_members for update to authenticated using(user_id=auth.uid() and can_chat(conversation_id)) with check(user_id=auth.uid());
create policy read_messages on messages for select to authenticated using(can_chat(conversation_id));
create policy read_courses on courses for select to authenticated using(active_user());
create policy read_tees on tees for select to authenticated using(active_user());
create policy read_holes on holes for select to authenticated using(active_user());
create policy read_rounds on rounds for select to authenticated using((user_id=auth.uid() and active_user()) or (status='published' and can_read_social(user_id,privacy)));
create policy insert_round on rounds for insert to authenticated with check(active_user() and user_id=auth.uid() and not verified);
create policy update_round on rounds for update to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid() and not verified);
create policy delete_round on rounds for delete to authenticated using(active_user() and user_id=auth.uid());
create policy read_scores on hole_scores for select to authenticated using(exists(select 1 from rounds where id=round_id));
create policy own_followers on followers for all to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid() and not approved and not_blocked(target_id));
create policy followers_requests on followers for select to authenticated using(active_user() and target_id=auth.uid());
create policy accept_follower on followers for update to authenticated using(active_user() and target_id=auth.uid()) with check(target_id=auth.uid());
create policy read_posts on posts for select to authenticated using(can_read_social(user_id,privacy) and (round_id is null or exists(select 1 from rounds where id=round_id)));
create policy own_posts on posts for all to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid() and active_user() and (round_id is null or exists(select 1 from rounds where id=round_id and user_id=auth.uid() and status='published' and rounds.privacy=posts.privacy)));
create policy read_comments on comments for select to authenticated using(exists(select 1 from posts where id=post_id));
create policy create_comment on comments for insert to authenticated with check(active_user() and user_id=auth.uid() and exists(select 1 from posts where id=post_id));
create policy own_comment on comments for delete to authenticated using(user_id=auth.uid());
create policy read_reactions on reactions for select to authenticated using(exists(select 1 from posts where id=post_id));
create policy own_reaction on reactions for all to authenticated using(user_id=auth.uid()) with check(active_user() and user_id=auth.uid() and exists(select 1 from posts where id=post_id));
create policy read_reviews on reviews for select to authenticated using(active_user() and not_blocked(target_id));
create policy create_review on reviews for insert to authenticated with check(reviewer_id=auth.uid() and valid_review(game_id,target_id));
create policy own_notifications on notifications for select to authenticated using(active_user() and user_id=auth.uid());
create policy read_notification on notifications for update to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_notification_preferences on notification_preferences for all to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid());
create policy create_report on reports for insert to authenticated with check(active_user() and user_id=auth.uid() and status='pending');
create policy own_reports on reports for select to authenticated using(active_user() and user_id=auth.uid());
create policy read_availability on availability for select to authenticated using(active_user() and expires_at>now() and not_blocked(user_id));
create policy own_availability on availability for all to authenticated using(active_user() and user_id=auth.uid()) with check(user_id=auth.uid() and expires_at>now() and expires_at<now()+interval '8 days');
create policy own_verification on verification_requests for select to authenticated using(user_id=auth.uid());
create policy request_verification on verification_requests for insert to authenticated with check(active_user() and user_id=auth.uid() and status='pending');
-- Solo RPC para escrituras sensibles. Lecturas y permisos mínimos por columna.
revoke all on all tables in schema public from anon;
grant select,insert,update,delete on all tables in schema public to authenticated;
revoke insert,update,delete on decisions,matches,conversations,conversation_members,messages,game_participants,hole_scores,account_roles from authenticated;
grant update(last_read_at) on conversation_members to authenticated;
grant update(is_admin,suspended) on account_roles to authenticated;
revoke update on notifications from authenticated;
grant update(read) on notifications to authenticated;
revoke update on followers from authenticated;
grant update(approved) on followers to authenticated;
revoke execute on all functions in schema public from public,anon;
grant execute on function public.is_admin(),public.active_user(),public.not_blocked(uuid),public.are_matched(uuid),public.in_game(uuid),public.can_see_game(uuid),public.can_chat(uuid),public.can_read_social(uuid,text),public.valid_review(uuid,uuid),public.decide(uuid,text),public.request_join(uuid),public.manage_game(uuid,uuid,text),public.rating_summary(),public.send_message(uuid,text),public.delete_my_account() to authenticated;
create index messages_conversation_time on messages(conversation_id,created_at);
create index games_date on games(starts_at);
create index rounds_user_date on rounds(user_id,played_at);
create index decisions_target on decisions(target_id,actor_id);
insert into clubs(name,city,description) values('Club Campestre de León','León','Registro inicial. Datos y acceso pendientes de confirmar.'),('El Bosque Country Club','León','Registro inicial. Datos y acceso pendientes de confirmar.'),('Club de Golf La Hacienda','Por confirmar','Nombre y ubicación pendientes de validación.');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('profile-images','profile-images',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy upload_own on storage.objects for insert to authenticated with check(bucket_id='profile-images' and (storage.foldername(name))[1]=auth.uid()::text and active_user());
create policy view_images on storage.objects for select to authenticated using(bucket_id='profile-images' and active_user() and exists(select 1 from profiles where id::text=(storage.foldername(name))[1] and (id=auth.uid() or (visibility<>'private' and not_blocked(id)))));
create policy delete_own_image on storage.objects for delete to authenticated using(bucket_id='profile-images' and (storage.foldername(name))[1]=auth.uid()::text);
alter publication supabase_realtime add table public.messages,public.notifications;
commit;
